# Check function exists
if 'calculate_total' not in local_vars:
    raise AssertionError('Task 1: Should define calculate_total function')

calc_func = local_vars['calculate_total']
if not callable(calc_func):
    raise AssertionError('Task 1: calculate_total should be a function')

# Test function with default tax_rate
try:
    result_default = calc_func(10, 50)
    expected_default = 10 * 50 * 1.05  # 525.0
    if abs(result_default - expected_default) > 0.001:
        raise AssertionError(f'Task 1: With default tax, calculate_total(10, 50) should return {expected_default}, got {result_default}')
except TypeError as e:
    if 'missing' in str(e) or 'required' in str(e):
        raise AssertionError('Task 1: tax_rate should have a default value of 0.05')
    raise AssertionError(f'Task 1: Function error - {str(e)}')

# Test function with custom tax_rate
result_custom = calc_func(2, 100, 0.15)
expected_custom = 2 * 100 * 1.15  # 230.0
if abs(result_custom - expected_custom) > 0.001:
    raise AssertionError(f'Task 1: calculate_total(2, 100, 0.15) should return {expected_custom}, got {result_custom}')

